import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    if server_hostname is None:
        server_hostname = host
    # Create a TCP socket and connect
    sock = socket.create_connection((host, port))
    try:
        # Wrap the socket with TLS, verifying certificate and hostname
        tls_sock = wrap_client_socket(sock, server_hostname, cafile)
        try:
            # Read up to 4096 bytes or until the first newline (inclusive)
            greeting = bytearray()
            while len(greeting) < 4096:
                chunk = tls_sock.recv(4096 - len(greeting))
                if not chunk:
                    # Connection closed
                    break
                greeting.extend(chunk)
                if b'\n' in chunk:
                    # Stop after first newline
                    break
            # Return bytes up to and including the first newline if present
            newline_index = greeting.find(b'\n')
            if newline_index != -1:
                return bytes(greeting[:newline_index + 1])
            else:
                return bytes(greeting)
        finally:
            tls_sock.close()
    except ssl.SSLError:
        # Propagate SSL errors as required
        raise
    finally:
        sock.close()

import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert against cafile and hostname,
    and return the server's greeting bytes up to and including the first newline or until close
    (max 4096 bytes). Raise ssl.SSLError or ssl.CertificateError on verification failure."""
    if server_hostname is None:
        server_hostname = host

    sock = socket.create_connection((host, port))
    try:
        tls_sock = wrap_client_socket(sock, server_hostname, cafile)
        # Read bytes until newline or EOF or 4096 bytes max
        greeting = bytearray()
        while len(greeting) < 4096:
            chunk = tls_sock.recv(4096 - len(greeting))
            if not chunk:
                # Connection closed by server
                break
            greeting.extend(chunk)
            if b"\n" in chunk:
                # Stop after first newline
                break
        # Return bytes up to and including first newline if present
        newline_index = greeting.find(b"\n")
        if newline_index != -1:
            return bytes(greeting[:newline_index + 1])
        else:
            return bytes(greeting)
    finally:
        try:
            tls_sock.close()
        except Exception:
            pass
        try:
            sock.close()
        except Exception:
            pass
